  ui_story_31730401_38_dialog_content = "Como proveedor de los mejores licores de Umbraton, mi extensa red de informantes es lo único más vasto que mi conocimiento de las bebidas.",
  ui_story_31730401_39_dialog_content = "Soy perfectamente consciente de sus planes para asaltar la Mansión Andersen esta noche.",
  ui_story_31730401_40_dialog_content = "Pero antes de hacerlo, seguramente te reunirás con el resto de Steelshafts en algún lugar, ¿no?",
