  ui_story_31730401_46_dialog_content = "¿Siempre podría recurrir al castigo escrito en tu contrato, en su lugar?",
  ui_story_31730401_47_dialog_content = "Aunque pensaría que una muerte rápida sería mucho más aceptable, ¿no estás de acuerdo?",
  ui_story_31730401_48_dialog_content = "P-Por favor, señor, sólo una noche más...",
  ui_story_31730401_49_dialog_content = "Me malinterpreta, Sr. Gray.",
  ui_story_31730401_50_dialog_content = "Tienes exactamente tres segundos para darme la información que necesito.",
  ui_story_31730401_51_dialog_content = "Tres-",
  ui_story_31730401_52_dialog_content = "¡O-bien! ¡Yo hablaré!",
  ui_story_31730401_53_dialog_content = "Yo hablaré...",
  ui_story_31730401_54_dialog_content = "Los Steelshaft se reunirán cerca de las ruinas de Maida Mesa, en una casa abandonada con tres árboles torcidos plantados en el patio.",
  ui_story_31730401_55_dialog_content = "Ya veo. Gracias por su gentil cooperación.",
  ui_story_31730401_56_dialog_content = "E-Espera, no entiendo...",
  ui_story_31730401_57_dialog_content = "¿Por qué quieres esta información en lugar del dinero que te debo?",
  ui_story_31730401_58_dialog_content = "Apareciste de la nada hace un mes con la intención de venderme licores raros y caros...",
  ui_story_31730401_59_dialog_content = "Entonces por qué...",
  ui_story_31730401_60_dialog_content = "No... T-Tú... ¡Tú!",
  ui_story_31730401_61_dialog_content = "Sabías que los Steelshaft me habían contratado, ¿no?",
  ui_story_31730401_62_dialog_content = "El alcohol, la deuda loca, y ahora esta visita...",
  ui_story_31730401_63_dialog_content = "¡Hiciste todo eso solo para poder averiguar su lugar de reunión!",
  ui_story_31730401_64_dialog_content = "Me malinterpreta, Sr. Gray.",
  ui_story_31730401_65_dialog_content = "Adquirí su ubicación hace mucho tiempo. Simplemente vine aquí para confirmarlo.",
  ui_story_31730401_66_dialog_content = "Ahora, por favor, tome asiento y descanse un rato.",
  ui_story_31730401_67_dialog_content = "Tendré que hurgar en tu tocador en busca de un disfraz adecuado, si no te importa...",
  ui_story_31730401_68_dialog_content = "Hmmm, esto servirá.",
  ui_story_31730401_69_dialog_content = "¡Oye! ¿Eres nuevo por aquí?",
  ui_story_31730401_70_dialog_content = "Sí.",
  ui_story_31730401_71_dialog_content = "¿Has confirmado su identidad? ¿Y recibió bien la señal secreta?",
  ui_story_31730401_72_dialog_content = "¡Si jefe! ¡Lo hizo todo bien!",
  ui_story_31730401_73_dialog_content = "Eh. ¿Cómo era tu nombre? Gris, ¿no?",
  ui_story_31730401_74_dialog_content = "Sí.",
  ui_story_31730401_75_dialog_content = "Eres más alto de lo que esperaba, pero supongo que eso no importa.",
  ui_story_31730401_76_dialog_content = "¿Ya están todos aquí?",
  ui_story_31730401_77_dialog_content = "¡Si jefe!",
  ui_story_31730401_78_dialog_content = "¡Muy bien, todos ustedes, escuchen! Es hora de revelar nuestro plan.",
  ui_story_31730401_79_dialog_content = "¡Solo lo digo una vez, así que escucha atentamente! ¡Una vez que termine de hablar, tomaremos todo el contrabando aquí y nos dirigiremos al próximo punto de encuentro!",
  ui_story_31730401_80_dialog_content = "Tenía algunos trajes hechos a la medida para parecerse a los que usaban los sirvientes de la familia Andersen. Los usaremos como disfraces para entrar.",
  ui_story_31730401_81_dialog_content = "Y recuerda, nuestro objetivo esta noche es Nina Andersen, ¡y solo Nina Andersen!",
  ui_story_31730401_82_dialog_content = "¡No te distraigas con ninguna de las cosas caras que hay en la Mansión Andersen! Una vez que tengamos a nuestro rehén, ¡lárguense de ahí!",
  ui_story_31730401_X82_dialog_content = "Y si alguno de ustedes comete el más mínimo error... Bueno, ya saben lo que les espera.",
  ui_story_31730401_X83_dialog_content = "No desperdicié todos estos años en Umbraton por nada.",
  ui_story_31730401_83_dialog_content = "Con la amada hija de Androma bajo nuestra custodia, estoy seguro de que pagará cualquier precio para recuperarla.",
  ui_story_31730401_84_dialog_content = "Repasaremos la infiltración y el rol específico de cada uno en el próximo punto de encuentro.",
  ui_story_31730401_85_dialog_content = "¿Me aclaré, muchachos? Si es así, ¡toma todo el contrabando que puedas y muévete!",
  ui_story_31730401_86_dialog_content = "Hmm, claro como el cristal.",
  ui_story_31730401_87_dialog_content = "Debo decir...",
  ui_story_31730401_88_dialog_content = "Si hubiera sabido lo simple e idiota que era tu plan desde el principio, nunca hubiera venido personalmente aquí.",
  ui_story_31730401_89_dialog_content = "¿Eh? ¿De qué diablos estás hablando, Gray?",
  ui_story_31730401_90_dialog_content = "Bueno, ya ves...",
  ui_story_31730401_91_dialog_content = "No soy el Sr. Gray, sino Minos, el mayordomo exclusivo de la familia Andersen.",
  ui_story_31730401_92_dialog_content = "Honestamente, incluso pronunciar el nombre de la familia Andersen en un lugar tan descuidado es un insulto desvergonzado al buen nombre de la Maestra.",
  ui_story_31730401_93_dialog_content = "¡Diablos!",
  ui_story_31730401_94_dialog_content = "¡Atrápenlo, terrones! Pase lo que pase, ¡no podemos dejar que este tipo se vaya de aquí con vida!",
  ui_story_31730401_95_dialog_content = "¡Toma esto!",
  ui_story_31730401_96_dialog_content = "Tus golpes carecen severamente de gracia.",
  ui_story_31730401_97_dialog_content = "¡Fuera del camino, muchachos! ¡Estoy disparando una bomba incendiaria!",
  ui_story_31730401_98_dialog_content = "Y tú, tu puntería es bastante lamentable. La próxima vez, arreglar ese espantoso peinado tuyo antes de disparar podría ayudar un poco.",
  ui_story_31730401_99_dialog_content = "Maldita sea... ¡Usaré mi espada en su lugar! ¡¡Te voy a cortar!!",
  ui_story_31730401_100_dialog_content = "Ah, mis disculpas, pero lo que voy a decir podría herir tu orgullo.",
  ui_story_31730401_101_dialog_content = "Tu habilidad con la espada ni siquiera puede comenzar a compararse con la de la hija de mi amo. Incluso PlayerName no tendría ningún problema en derrotarte.",
  ui_story_31730401_X101_dialog_content = "¡Eres un inútil!",
  ui_story_31730401_102_dialog_content = "¡Olvídate de el! ¡Solo toma las cosas y vete!",
  ui_story_31730401_103_dialog_content = "Menos mal que vine preparado. ¡Soy el único que sabe exactamente dónde está el próximo punto de encuentro!",
  ui_story_31730401_104_dialog_content = "Seis en el techo, diez fuera de la casa y... quince dentro de la casa.",
  ui_story_31730401_105_dialog_content = "Tal como lo predije, más o menos.",
  ui_story_31730401_106_dialog_content = "En ese caso... Creo que es hora de acabar con este jueguecito.",
  ui_story_31730401_107_dialog_content = "Con un evento tan importante al que asistir esta noche, realmente deseaba evitar mancharme las manos con el hedor de las alimañas...",
  ui_story_31730401_108_dialog_content = "Pero como las alimañas suelen escabullirse, supongo que debo terminar esto rápidamente y quitarme el hedor cuando regrese.",
  ui_story_31730401_109_dialog_content = "Por otra parte, como mayordomo orgulloso, siempre estoy feliz de limpiar las cosas.",
  ui_story_31730401_110_dialog_content = "Así que, por favor, no tengas miedo... De hecho, soy bastante amable.",
  ui_story_31730401_111_dialog_content = "El primer paso para mantener un hogar limpio y ordenado:",
  ui_story_31730401_112_dialog_content = "— es recoger toda la basura y disponerla adecuadamente.",
  ui_story_31730401_113_dialog_content = "Saludos, PlayerName, y bienvenido de nuevo a la casa de mi amo.",
  ui_story_31730401_114_dialog_content = "¿Descansaste adecuadamente en tu habitación? ¿Fueron de su agrado los refrigerios y dispositivos de entretenimiento?",
  ui_story_31730401_115_option_content = "¡Absolutamente!",
  ui_story_31730401_116_dialog_content = "Justo la respuesta que quería oír.",
  ui_story_31730401_117_dialog_content = "¿Eh, Minos...? ¿Te sientes bien? no te ves muy bien...",
  ui_story_31730401_118_option_content = "Si pero...",
  ui_story_31730401_119_dialog_content = "Pareces exhausto, Minos.",
  ui_story_31730401_120_dialog_content = "Debes haber estado muy ocupado hoy.",
  ui_story_31730401_121_dialog_content = "Para nada.",
  ui_story_31730401_122_dialog_content = "Mis disculpas si mi apariencia le dio motivo de preocupación.",
  ui_story_31730401_123_dialog_content = "Preocupar a nuestros estimados invitados es una de las peores cosas que puede hacer un mayordomo.",
  ui_story_31730401_124_dialog_content = "¿Quizás debería usar algunos cosméticos femeninos para alegrar mi apariencia?",
  ui_story_31730401_125_dialog_content = "No tenía idea de que tuvieras tal, um... vanidad, Minos.",
  ui_story_31730401_126_dialog_content = "Oh, solo estoy bromeando.",
  ui_story_31730401_127_dialog_content = "Ahora bien, Sr. Navegante, diríjase al salón de banquetes y disfrute de su comida.",
  ui_story_31730401_128_dialog_content = "Desafortunadamente, todavía tengo otros asuntos que atender.",
  ui_story_31730401_129_dialog_content = "Antes de que la fiesta comience en serio, debo hacer un informe urgente a mi amo.",
  ui_story_31730401_130_dialog_content = "Si necesita algo, no dude en preguntar a cualquiera de los sirvientes. Me reuniré contigo y con los demás en un momento.",
  ui_story_31730401_131_dialog_content = "Claro, puedo cuidarme solo, no te preocupes.",
  ui_story_31730401_132_dialog_content = "Es un gran honor tenerlos a todos como invitados en mi casa esta noche.",
  ui_story_31730401_133_dialog_content = "Como ya habrán escuchado, sí... tengo un pequeño anuncio que hacer.",
  ui_story_31730401_134_dialog_content = "Nada trascendental, de ninguna manera. Más bien, es simplemente la afirmación de una nueva dirección en la que crecerá la familia Andersen.",
  ui_story_31730401_135_dialog_content = "Damas y caballeros, es un placer para mí anunciar—",
  ui_story_31730401_136_dialog_content = "¡A partir de este día, la familia Andersen ingresará oficialmente a la industria de bienes raíces!",
  ui_story_31730401_137_dialog_content = "¡Felicidades! ¡Felicidades, Androma!",
  ui_story_31730401_138_dialog_content = "¿Es este el poder de la antigua nobleza?",
  ui_story_31730401_139_dialog_content = "Parece que todas las habitaciones han sido abastecidas con todo tipo de refrigerios e instalaciones recreativas... ¡Si no lo supiera mejor, diría que todavía estamos en Lumopolis!",
  ui_story_31730401_140_dialog_content = "Y con este pequeño anuncio fuera del camino, les pido por favor que disfruten de todo lo que ofrece nuestro banquete.",
  ui_story_31730401_141_dialog_content = "¿Qué fue eso? ¿Escuchaste eso hace un momento?",
  ui_story_31730401_142_dialog_content = "¿Fue eso una explosión?",
  ui_story_31730401_143_dialog_content = "Sí, creo que también lo escuché...",
  ui_story_31730401_144_dialog_content = "¡No se adelanten! ¡El Maestro Androma probablemente ordenó fuegos artificiales para esta noche!",
  ui_story_31730401_145_dialog_content = "Bueno, ¿deberíamos salir y ver?",
  ui_story_31730401_146_dialog_content = "Supongo que deberíamos... Suena como fuegos artificiales, después de todo.",
  ui_story_31730401_147_dialog_content = "¿Se ha encargado todo el contrabando?",
  ui_story_31730401_148_dialog_content = "Si señor.",
  ui_story_31730401_149_dialog_content = "He arreglado que alguien encienda los fuegos artificiales. Miss Nina también insiste bastante en verlos.",
  ui_story_31730401_150_dialog_content = "Ya veo. Bien hecho, Minos.",
  ui_story_31730401_151_dialog_content = "Ah, y el vino que nos diste hoy es absolutamente exquisito.",
  ui_story_31730401_152_dialog_content = "Qué amable de su parte decir eso, Maestro... Pero todo esto es parte de mi deber como su humilde mayordomo.",
  ui_story_31730401_153_dialog_content = "Cuidado, señorita Nina. ¡No te quedes fuera demasiado tiempo, no sea que te resfríes!",
  ui_story_31730401_154_dialog_content = "¡Sé que sé!",
  ui_story_31730401_155_dialog_content = "Ah, ¿y Minos?",
  ui_story_31730401_156_dialog_content = "¿Cuándo estará lista la casa embrujada? ¡Compré todo tipo de accesorios para ello!",
  ui_story_31730401_157_dialog_content = "Pronto, señorita.",
  ui_story_31730401_158_dialog_content = "Confía en mí, quiero decir, muy pronto.",
  ui_story_31730601_2_dialog_content = "¡No—!",
  ui_story_31730601_3_dialog_content = "He estado comprando aquí todo el tiempo. ¿Cómo podría de repente... estar cerrado...",
  ui_story_31730601_4_dialog_content = "¿Vaya? ¿No es este el Sr. Navegante?",
  ui_story_31730601_5_dialog_content = "Escuché un grito hace un momento y vine a verificar. ¿Estás en algún tipo de problema?",
  ui_story_31730601_6_dialog_content = "Ah... Perdón por molestarte. En realidad no es gran cosa.",
  ui_story_31730601_7_dialog_content = "La tienda donde siempre solía comprar cerró repentinamente, dejándome sin saber dónde comprar ahora.",
  ui_story_31730601_8_dialog_content = "Los negocios en Umbraton van y vienen todo el tiempo. A menudo tienen que cerrar por una razón u otra.",
  ui_story_31730601_9_dialog_content = "Por lo tanto, es aconsejable que no te inscribas en la membresía, ya que hay una alta probabilidad de ser estafado.",
  ui_story_31730601_10_dialog_content = "... No es como si tuviera suficiente dinero para inscribirme en la membresía.",
  ui_story_31730601_11_dialog_content = "¿Qué le gustaría comprar?",
  ui_story_31730601_12_dialog_content = "Hmm... Quiero comprar papel de envolver y cintas para prepararme para las vacaciones.",
  ui_story_31730601_13_dialog_content = "¿Oh? En ese caso, resulta que conozco un lugar para ti.",
  ui_story_31730601_14_dialog_content = "Por favor, permíteme guiarte el camino.",
  ui_story_31730601_15_dialog_content = "Eso es muy amable de tu parte. ¿También acabas de terminar de comprar? Con todas las bolsas aquí...",
  ui_story_31730601_16_dialog_content = "Correcto, sí. He estado en varias tiendas, tratando de elegir los artículos más rentables.",
  ui_story_31730601_17_dialog_content = "Por favor, no te preocupes. De hecho, estamos en camino. El clima ha estado húmedo últimamente, así que necesito comprar algo de incienso repelente de insectos.",
  ui_story_31730601_18_dialog_content = "De lo contrario... Me temo que lo encontrarás divertido. La mujer joven podría hacer otra rabieta.",
  ui_story_31730601_19_dialog_content = "No, no... Déjame darte un poco de ayuda!",
  ui_story_31730601_20_dialog_content = "Gracias por tu amabilidad entonces.",
  ui_story_31730601_21_dialog_content = "Vaya, ¿todos los productos en las bolsas ya han sido ordenados en realidad?",
  ui_story_31730601_22_dialog_content = "Realmente cubres todas las bases como mayordomo.",
  ui_story_31730601_23_dialog_content = "Es casi como si hubieras nacido para ser mayordomo. Apenas es como...",
  ui_story_31730601_24_dialog_content = "¿Quieres decir un asesino?",
  ui_story_31730601_25_dialog_content = "Ah, lo siento... Creo que me dejé llevar un poco...",
  ui_story_31730601_26_dialog_content = "No te preocupes, alguien ha dicho esto sobre mí antes...",
  ui_story_31730601_27_dialog_content = "Todavía tenemos un largo camino por recorrer. ¿Quieres escuchar algunas historias de mi pasado?",
  ui_story_31730601_28_dialog_content = "¡Claro!",
  ui_story_31730601_29_dialog_content = "Recordando, fue ella quien salvó mi vida...",
  ui_story_31730601_30_dialog_content = "<color=#e8d9bb>Ka-thunk!!</color>",
  ui_story_31730601_31_dialog_content = "Hmph, qué toro tan terco para domesticar...",
  ui_story_31730601_32_dialog_content = "¿Fuiste tú el que eliminó a ocho de mis chicos?",
  ui_story_31730601_33_dialog_content = "He venido con un regalo del maestro, ¿y así es como pagas su amabilidad...?",
  ui_story_31730601_34_dialog_content = "Qué vergonzoso. ¡Deberías avergonzarte de llamarte aliado de la familia!",
  ui_story_31730601_35_dialog_content = "¿Amabilidad? ¿Aliados? No, si vives aquí, deberías saber que no nos molestamos con esas cosas.",
  ui_story_31730601_36_dialog_content = "El poder lo es todo, no necesitamos una familia débil.",
  ui_story_31730601_37_dialog_content = "¿Cómo te atreves a hacer un discurso tan codicioso y desvergonzado?",
  ui_story_31730601_38_dialog_content = "Je, les mostraré a todos—",
  ui_story_31730601_39_dialog_content = "¡¿?!",
  ui_story_31730601_40_dialog_content = "¡Derríbalo!",
  ui_story_31730601_41_dialog_content = "¡N-No dejes que se acerque al jefe!",
  ui_story_31730601_42_dialog_content = "¡Traición y engaño... Esa es la verdadera debilidad!",
  ui_story_31730601_43_dialog_content = "... Casi.",
  ui_story_31730601_44_dialog_content = "Qué tonto tan lamentable. Cualquier asesino sabe que la mejor manera de mantenerse vivo es unirse al grupo más fuerte.",
  ui_story_31730601_45_dialog_content = "Haz lo que quieras, no me importa...",
  ui_story_31730601_46_dialog_content = "No soy tú... Nunca traicionaría al maestro y a la mujer joven.",
  ui_story_31730601_47_dialog_content = "Entonces, si te llevé a la negociación con los Andersen...",
  ui_story_31730601_48_dialog_content = ".. ¿y mostrarle a tu maestro lo lamentable que te has vuelto?",
  ui_story_31730601_49_dialog_content = "Tú—!",
  ui_story_31730601_50_dialog_content = "Cállalo, luego mételo en el estuche que trajo.",
  ui_story_31730601_51_dialog_content = "¡Sí!",
  ui_story_31730601_52_dialog_content = "Dado que los Andersen me dieron un regalo, debería devolver el gesto.",
  ui_story_31730601_53_dialog_content = "¡Bestia! Debería matarte... Debería haber... ¡¡¡Urgh!!!",
  ui_story_31730601_54_dialog_content = "<color=#e8d9bb>Así como así, me metieron en el maletín y me colocaron en un carruaje.</color>",
  ui_story_31730601_55_dialog_content = "<color=#e8d9bb>Estaban apurados, pero se detuvieron. Quizás hubo un choque o algo así, o otra pandilla.</color>",
  ui_story_31730601_56_dialog_content = "<color=#e8d9bb>Luché por salir del carruaje pero no puedo abrir el maletín.</color>",
  ui_story_31730601_57_dialog_content = "<color=#e8d9bb>Entonces, sentí que unas manos débiles daban un empujón tembloroso a la caja en la que estaba...</color>",
  ui_story_31730601_58_dialog_content = "<color=#e8d9bb>Ruido sordo-</color>",
  ui_story_31730601_59_dialog_content = "...",
  ui_story_31730601_60_dialog_content = "No es dinero sucio ni joyas de la pandilla...",
  ui_story_31730601_61_dialog_content = "Te he defraudado, ¿no?",
  ui_story_31730601_62_dialog_content = "¡...!",
  ui_story_31730601_63_dialog_content = "Pensé que era solo un gatito o un cachorro, pero... pero...",
  ui_story_31730601_64_dialog_content = "El mundo es un tapiz de eventos inesperados.",
  ui_story_31730601_65_dialog_content = "Si no quieres meterte en problemas, será mejor que te vayas...",
  ui_story_31730601_66_dialog_content = "Yo... Yo sé...",
  ui_story_31730601_67_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_31730601_68_dialog_content = "¡¿...?!",
  ui_story_31730601_69_dialog_content = "¿Qué vas a hacer... ¿¡Por qué sigues empujándome!?",
  ui_story_31730601_70_dialog_content = "Estarías muerto si te dejara aquí, ¿verdad?",
  ui_story_31730601_71_dialog_content = "Conozco un hospital subterráneo que se especializa en tratar a personas como tú.",
  ui_story_31730601_72_dialog_content = "Te llevaré allí, pero en cuanto a qué pasa después... Realmente no lo sabría...",
  ui_story_31730601_73_dialog_content = "¿Sabiendo quién soy, aún quieres salvarme?",
  ui_story_31730601_74_dialog_content = "N-No me gusta el olor a sangre en ti...",
  ui_story_31730601_75_dialog_content = "Pero incluso con un olor tan fuerte a sangre, todavía puedo percibir el aroma de la harina y la mantequilla en ti.",
  ui_story_31730601_76_dialog_content = "Esos verdaderos gángsters... Huelen a pipas, licor barato y casinos.",
  ui_story_31730601_77_dialog_content = "Entonces eres como un cocinero o un mayordomo, un buen niño que quedó atrapado en este lío, ¿verdad?",
  ui_story_31730601_78_dialog_content = "Esa era una dama aguda.",
  ui_story_31730601_79_dialog_content = "Y bajo esas circunstancias... es verdaderamente admirable.",
  ui_story_31730601_80_dialog_content = "Ah, hemos llegado. Este es el lugar.",
  ui_story_31730601_81_dialog_content = "¿Es este tu amigo, joven señor mayordomo?",
  ui_story_31730601_82_dialog_content = "Es un amigo cercano, y es la primera vez que viene aquí, ¿te importaría darnos un descuento?",
  ui_story_31730601_83_dialog_content = "No hay problema, por supuesto... un amigo cercano del joven Sr. Mayordomo.",
  ui_story_31730601_84_dialog_content = "N-Encantado de conocerte.",
  ui_story_31730601_85_dialog_content = "*olfateando*",
  ui_story_31730601_86_dialog_content = "¿Eh... Yo, tengo un cierto olor en mí?",
  ui_story_31730601_87_dialog_content = "Ah, lo siento, mi vista no es muy buena, así que suelo recordar a los clientes por su olor.",
  ui_story_31730601_88_dialog_content = "Tú... Hueles como el cielo.",
  ui_story_31730601_89_dialog_content = "Es tan claro, brillante y progresista. Es un soplo de aire fresco.",
  ui_story_31730601_90_dialog_content = "Combina tan bien con el aroma mantecoso y harinoso del joven Sr. Mayordomo.",
  ui_story_31730601_91_dialog_content = "¿Trabajas en el Centro de Lanzadera?",
  ui_story_31730601_92_dialog_content = "Tengo ramos de flores y aromaterapia adecuados para dirigibles. ¿Te gustaría hacer una compra?",
  ui_story_31730601_93_dialog_content = "Sí, por favor. Realmente necesito algunos de esos.",
  ui_story_31730601_94_dialog_content = "... ¿Entonces esta es la dama que te salvó?",
  ui_story_31730601_95_dialog_content = "Sí, después de todo, fue un favor que me salvó la vida. Ella me ayudó a escapar y regresar a los Andersen.",
  ui_story_31730601_96_dialog_content = "Ahora que es mayor, a menudo vengo a verla.",
  ui_story_31730601_97_dialog_content = "Y tú me trajiste aquí...",
  ui_story_31730601_98_option_content = "¿Para que pueda entenderte mejor?",
  ui_story_31730601_99_dialog_content = "Oh, no esperaba que entendieras las cosas de esta manera.",
  ui_story_31730601_100_dialog_content = "Pero de alguna manera, sí. Mi pasado está inextricablemente vinculado a la historia de derramamiento de sangre de la familia.",
  ui_story_31730601_101_dialog_content = "Y compartir contigo algo que nunca le he contado a nadie antes realmente me brinda una sensación de alivio.",
  ui_story_31730601_102_option_content = "¿Para que yo también pueda hacerle compañía?",
  ui_story_31730601_103_dialog_content = "Por supuesto, probablemente estaría aún más feliz con más gente alrededor.",
  ui_story_31730601_104_dialog_content = "Y esta es también mi primera vez llevando a alguien que sabe sobre este asunto a su lugar.",
  ui_story_31730601_105_dialog_content = "También has llegado a conocer uno de mis secretos.",
  ui_story_31730601_106_dialog_content = "Sería mi mayor honor.",
  ui_story_31730601_107_dialog_content = "De todos modos, este es un lugar maravilloso, siéntete libre de hacer tu selección aquí.",
  ui_story_31730601_108_dialog_content = "¡Gracias, estoy segura de que encontraré algo que me guste aquí!"
}
return config
